// ══════════════════════════════════════════════════════
// PARSER — Détecter CALLBACK (clic bouton) ou MESSAGE (texte)
// ══════════════════════════════════════════════════════
const body = $input.first().json.body || $input.first().json;

if (body.callback_query) {
  const cb = body.callback_query;
  return [{
    json: {
      type:            'CALLBACK',
      chatId:          String(cb.message.chat.id),
      callbackQueryId: cb.id,
      data:            cb.data,
      originalMsgId:   cb.message.message_id
    }
  }];
}

if (body.message) {
  const msg = body.message;
  // Récupérer le fileId depuis le message original auquel l'user répond
  const replyText = msg.reply_to_message?.text || '';
  const refMatch  = replyText.match(/Réf:\s*`?([^`\n]+)`?/);
  return [{
    json: {
      type:     'MESSAGE',
      chatId:   String(msg.chat.id),
      text:     (msg.text || '').trim(),
      fileIdFromReply: refMatch ? refMatch[1].trim() : null
    }
  }];
}

// Ignorer tout autre type
return [];

// ══════════════════════════════════════════════════════
// BRANCHE CALLBACK — Parser le choix du bouton
// Format: CAT|CHOIX|FILE_ID
// ══════════════════════════════════════════════════════
const d = $input.first().json;
const parts = (d.data || '').split('|');
if (parts.length < 3 || parts[0] !== 'CAT') {
  throw new Error('callback_data invalide: ' + d.data);
}
return [{
  json: {
    ...d,
    choix:          parts[1],
    fileId:         parts[2],
    isVentilation:  parts[1] === 'VENTILER'
  }
}];

// ══════════════════════════════════════════════════════
// FUSIONNER — Catégorie choisie + données Staging
// ══════════════════════════════════════════════════════
const cbData  = $('🔍 Parser Choix Bouton').first().json;
const staging = $input.first().json;
const cat     = cbData.choix;
const isAutonome = cat === 'AUTONOME';

const FISCAL   = ['PRO','AUTONOME'];
const isFiscal = FISCAL.includes(cat);
let fiscalYear = new Date().getFullYear();
try { if (staging.Date) fiscalYear = new Date(staging.Date).getFullYear(); } catch(e) {}

const targetFolderName = isFiscal ? `Impôts ${fiscalYear}` : '!GED_ARCHIVE';

function sanitize(s) {
  if (!s && s !== 0) return 'INCONNU';
  return String(s).toUpperCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g,'')
    .replace(/[^A-Z0-9-]/g,'_').replace(/_{2,}/g,'_')
    .replace(/^_+|_+$/g,'').substring(0,40);
}

const date    = staging.Date || new Date().toISOString().split('T')[0];
const montant = String(staging.Montant_Total_TTC || 0).replace('.','-');
const fileName = [
  date, sanitize(cat), sanitize(staging.Emetteur),
  sanitize((staging.Sous_Categorie||'')+'_'+(staging.Objet||'')),
  sanitize(staging.Beneficiaire), montant
].join('-') + '.pdf';

return [{
  json: {
    // Données originales staging
    fileId:          cbData.fileId,
    chatId:          cbData.chatId,
    Date:            staging.Date || '',
    Emetteur:        staging.Emetteur || '',
    Objet:           staging.Objet || '',
    Beneficiaire:    staging.Beneficiaire || '',
    Sous_Categorie:  staging.Sous_Categorie || '',
    source:          staging.source || '',
    originalFileId:  staging.fileId || cbData.fileId,
    // Données calculées
    finalCategorie:  cat,
    finalFileName:   fileName,
    isFiscal:        isFiscal,
    fiscalYear:      fiscalYear,
    targetFolderName:targetFolderName,
    impotsParentId:  '15HF0df8cMV1ebrLRqwLxWcT6r5oD5AnY',
    archiveFolderId: '1-7GCiI5ndlC2V0698iFwTCxuyKsYsG7m',
    // Colonnes Journal Fiscal
    jDate:          staging.Date || '',
    jEmetteur:      staging.Emetteur || '',
    jCategorie:     cat,
    jSousCategorie: staging.Sous_Categorie || '',
    jObjet:         staging.Objet || '',
    jBeneficiaire:  staging.Beneficiaire || '',
    jNet:           isAutonome ? (staging.Montant_Net  || '') : '',
    jTPS:           isAutonome ? (staging.TPS          || '') : '',
    jTVQ:           isAutonome ? (staging.TVQ          || '') : '',
    jTTC:           staging.Montant_Total_TTC || '',
    jLien:          '',
    jSource:        staging.source || ''
  }
}];

// ══════════════════════════════════════════════════════
// BRANCHE MESSAGE — Calcul TPS/TVQ depuis montant saisi
// ══════════════════════════════════════════════════════
const d = $input.first().json;
const rawText = d.text || '0';
const fileId  = d.fileIdFromReply;

if (!fileId) {
  throw new Error('fileId introuvable dans la réponse. Vérifier force_reply.');
}

const net = parseFloat(rawText.replace(',','.').replace(/[^0-9.]/g,''));
if (isNaN(net) || net <= 0) {
  throw new Error(`Montant invalide: "${rawText}". Saisir un nombre ex: 125.50`);
}

const TPS = Math.round(net * 0.05    * 100) / 100;
const TVQ = Math.round(net * 0.09975 * 100) / 100;
const TTC = Math.round((net + TPS + TVQ) * 100) / 100;

return [{
  json: {
    ...d,
    fileId:         fileId,
    montantNet:     net,
    montantTPS:     TPS,
    montantTVQ:     TVQ,
    montantTTC:     TTC
  }
}];

// ══════════════════════════════════════════════════════
// FUSIONNER — Ventilation calculée + données Staging
// ══════════════════════════════════════════════════════
const ventData = $('🧮 Calcul TPS/TVQ').first().json;
const staging  = $input.first().json;

let fiscalYear = new Date().getFullYear();
try { if (staging.Date) fiscalYear = new Date(staging.Date).getFullYear(); } catch(e) {}
const targetFolderName = `Impôts ${fiscalYear}`;

function sanitize(s) {
  if (!s && s !== 0) return 'INCONNU';
  return String(s).toUpperCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g,'')
    .replace(/[^A-Z0-9-]/g,'_').replace(/_{2,}/g,'_')
    .replace(/^_+|_+$/g,'').substring(0,40);
}

const date    = staging.Date || new Date().toISOString().split('T')[0];
const montant = String(ventData.montantTTC).replace('.','-');
const fileName = [
  date, 'AUTONOME', sanitize(staging.Emetteur),
  sanitize((staging.Sous_Categorie||'')+'_'+(staging.Objet||'')),
  sanitize(staging.Beneficiaire), montant
].join('-') + '.pdf';

return [{
  json: {
    fileId:          ventData.fileId,
    chatId:          ventData.chatId,
    Date:            staging.Date || '',
    Emetteur:        staging.Emetteur || '',
    Sous_Categorie:  staging.Sous_Categorie || '',
    Objet:           staging.Objet || '',
    Beneficiaire:    staging.Beneficiaire || '',
    source:          staging.source || '',
    originalFileId:  staging.fileId || ventData.fileId,
    finalCategorie:  'AUTONOME',
    finalFileName:   fileName,
    isFiscal:        true,
    fiscalYear:      fiscalYear,
    targetFolderName:targetFolderName,
    impotsParentId:  '15HF0df8cMV1ebrLRqwLxWcT6r5oD5AnY',
    archiveFolderId: '1-7GCiI5ndlC2V0698iFwTCxuyKsYsG7m',
    jDate:          staging.Date || '',
    jEmetteur:      staging.Emetteur || '',
    jCategorie:     'AUTONOME',
    jSousCategorie: staging.Sous_Categorie || '',
    jObjet:         staging.Objet || '',
    jBeneficiaire:  staging.Beneficiaire || '',
    jNet:           ventData.montantNet,
    jTPS:           ventData.montantTPS,
    jTVQ:           ventData.montantTVQ,
    jTTC:           ventData.montantTTC,
    jLien:          '',
    jSource:        staging.source || ''
  }
}];

// ══════════════════════════════════════════════════════
// MERGE — Récupérer les données fusionnées
// qu'elles viennent de la branche Catégorie ou Ventilation
// ══════════════════════════════════════════════════════
// Ce nœud reçoit soit depuis cb-n10 soit depuis cb-n14
// Les deux ont le même format de données
return [$input.first()];

