// Résoudre l'ID final du dossier cible
// Priorité: dossier nouvellement créé > dossier trouvé
const mergeData = $('⚙️ Merge Données Archivage').first().json;

let folderId = null;

// Essayer le dossier créé
try {
  const c = $('📁 Créer Dossier').first().json;
  if (c.id) folderId = c.id;
} catch(e) {}

// Sinon le dossier trouvé
if (!folderId) {
  try {
    const f = $('🔍 Chercher Dossier Cible').first().json;
    if (f.files && f.files.length > 0) folderId = f.files[0].id;
  } catch(e) {}
}

// Fallback
if (!folderId) {
  folderId = mergeData.isFiscal
    ? mergeData.impotsParentId
    : mergeData.archiveFolderId;
}

return [{ json: { ...mergeData, resolvedFolderId: folderId } }];

const d     = $('📌 Résoudre ID Dossier').first().json;
const drive = $('☁️ Upload Renommé').first().json;
return [{ json: { ...d, jLien: drive.webViewLink || '' } }];
